<?php
namespace App\Observers;use App\Jobs\DeleteProductFromGoogleMerchant;use App\Jobs\SyncProductToGoogleMerchant;use App\Models\Product;class ProductObserver{public function saved(Product $p):void{$this->queueSyncWhenEligible($p);}public function restored(Product $p):void{$this->queueSyncWhenEligible($p);}public function deleted(Product $p):void{if(config('merchant.enabled')&&$p->merchant_last_synced_at)DeleteProductFromGoogleMerchant::dispatch($p->id)->afterCommit();}private function queueSyncWhenEligible(Product $p):void{if(config('merchant.enabled')&&$p->merchant_sync_enabled&&$p->status==='active'&&$p->merchant_ready)SyncProductToGoogleMerchant::dispatch($p->id)->afterCommit();}}
